package com.pratik.imagetap;
import android.content.Context;import android.graphics.*;import android.view.*;import java.util.function.Consumer;
/** A temporary touchable overlay. Never dispatches input to the underlying application. */
final class MarkerPicker extends View {
 final ActionType action;final Consumer<float[]> finished;final Paint paint=new Paint(3);float x,y,ex,ey;int drag;boolean controlsBottom;final RectF save=new RectF(),cancel=new RectF(),heading=new RectF();
 MarkerPicker(Context c,TimedAction value,Consumer<float[]> finished){super(c);action=value.action;x=value.x;y=value.y;ex=value.endX;ey=value.endY;this.finished=finished;setContentDescription("Position action markers. Drag the start circle and swipe end circle. Save or cancel.");setFocusable(true);}
 float dp(float v){return Ui.dp(getContext(),v);}
 @Override protected void onDraw(Canvas c){c.drawColor(0x33071220);float w=getWidth(),h=getHeight();paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(3));paint.setColor(Ui.GREEN);if(action.swipe()){c.drawLine(x*w,y*h,ex*w,ey*h,paint);drawMarker(c,ex*w,ey*h,"END",0xffb3c9f2);}drawMarker(c,x*w,y*h,action.swipe()?"START":"TAP",Ui.GREEN);
  float top=controlsBottom?h-dp(162):dp(42);heading.set(dp(12),top,w-dp(12),top+dp(58));paint.setStyle(Paint.Style.FILL);paint.setColor(Ui.SURFACE);c.drawRoundRect(dp(12),top,w-dp(12),top+dp(120),dp(18),dp(18),paint);paint.setColor(Ui.CREAM);paint.setTextSize(dp(15));c.drawText(action.label+" · move panel ↕",dp(24),top+dp(26),paint);paint.setTextSize(dp(11));c.drawText("Drag markers. Tap heading to move this panel.",dp(24),top+dp(47),paint);
  cancel.set(dp(22),top+dp(63),w/2-dp(5),top+dp(108));save.set(w/2+dp(5),top+dp(63),w-dp(22),top+dp(108));paint.setColor(0xff24334a);c.drawRoundRect(cancel,dp(12),dp(12),paint);paint.setColor(Ui.CREAM);c.drawRoundRect(save,dp(12),dp(12),paint);paint.setTextSize(dp(14));paint.setColor(Ui.CREAM);c.drawText("Cancel",cancel.centerX()-paint.measureText("Cancel")/2,cancel.centerY()+dp(5),paint);paint.setColor(Ui.BG);c.drawText("Save position",save.centerX()-paint.measureText("Save position")/2,save.centerY()+dp(5),paint);
 }
 void drawMarker(Canvas c,float px,float py,String text,int color){paint.setStyle(Paint.Style.FILL);paint.setColor(0xc0111d30);c.drawCircle(px,py,dp(25),paint);paint.setStyle(Paint.Style.STROKE);paint.setColor(color);paint.setStrokeWidth(dp(3));c.drawCircle(px,py,dp(23),paint);c.drawLine(px-dp(32),py,px+dp(32),py,paint);c.drawLine(px,py-dp(32),px,py+dp(32),paint);paint.setStyle(Paint.Style.FILL);paint.setTextSize(dp(10));c.drawText(text,px-paint.measureText(text)/2,py-dp(35),paint);}
 @Override public boolean onTouchEvent(android.view.MotionEvent e){float nx=Math.max(.001f,Math.min(.999f,e.getX()/getWidth())),ny=Math.max(.001f,Math.min(.999f,e.getY()/getHeight()));if(e.getAction()==MotionEvent.ACTION_DOWN){if(save.contains(e.getX(),e.getY())){drag=3;return true;}if(cancel.contains(e.getX(),e.getY())){drag=4;return true;}if(heading.contains(e.getX(),e.getY())){drag=5;return true;}drag=action.swipe()&&Math.hypot(e.getX()-ex*getWidth(),e.getY()-ey*getHeight())<dp(40)?2:1;}if(e.getAction()==MotionEvent.ACTION_UP&&drag==5){controlsBottom=!controlsBottom;drag=0;invalidate();performClick();return true;}if(e.getAction()==MotionEvent.ACTION_UP&&(drag==3||drag==4)){if(drag==3&&save.contains(e.getX(),e.getY())){boolean valid=!action.swipe()||(action==ActionType.LEFT?x-ex:action==ActionType.RIGHT?ex-x:action==ActionType.UP?y-ey:ey-y)*(action==ActionType.LEFT||action==ActionType.RIGHT?getWidth():getHeight())>=12;if(valid)finished.accept(new float[]{x,y,ex,ey});else android.widget.Toast.makeText(getContext(),"Move the start and end markers farther apart in the swipe direction.",android.widget.Toast.LENGTH_LONG).show();}if(drag==4&&cancel.contains(e.getX(),e.getY()))finished.accept(null);drag=0;performClick();return true;}if(drag==1){float dx=nx-x,dy=ny-y;x=nx;y=ny;ex=Math.max(.001f,Math.min(.999f,ex+dx));ey=Math.max(.001f,Math.min(.999f,ey+dy));}else if(drag==2){if(action==ActionType.LEFT)ex=Math.max(.001f,Math.min(x-.01f,nx));if(action==ActionType.RIGHT)ex=Math.min(.999f,Math.max(x+.01f,nx));if(action==ActionType.UP)ey=Math.max(.001f,Math.min(y-.01f,ny));if(action==ActionType.DOWN)ey=Math.min(.999f,Math.max(y+.01f,ny));}if(action==ActionType.LEFT||action==ActionType.RIGHT)ey=y;if(action==ActionType.UP||action==ActionType.DOWN)ex=x;invalidate();if(e.getAction()==MotionEvent.ACTION_UP||e.getAction()==MotionEvent.ACTION_CANCEL)drag=0;return true;}
 @Override public boolean performClick(){super.performClick();return true;}
}
